1: import type { LoadOptions, Redact, RedactLabel } from "@desert-ant-labs/redact/native";
2: import { Redact as NativeRedact } from "@desert-ant-labs/redact/native";
3: import type { PiiCategory, PiiRule, RedactionDetail, RedactionResult, RedactorConfig } from "../types.js";
4: import { defaultRules, findRuleByIdOrLabel, RULE_ID_TO_LABEL } from "../rules/default-rules.js";
5: 
6: /** Configuration options for RedactorService initialization. */
7: export interface RedactorServiceOptions {
8:   /** Optional options passed to Redact.load(...) (e.g. offline directory or cacheRoot). */
9:   loadOptions?: LoadOptions;
10:   /** Optional pre-instantiated or mock Redact engine (useful for unit testing). */
11:   redactInstance?: Redact;
12: }
