1: import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
2: import type { RedactorService } from "../services/redactor.js";
3: 
4: export function registerPiiCommands(pi: ExtensionAPI, redactor: RedactorService): void {
5:   pi.registerCommand("pii", {
6:     description: "Manage PII redaction (status, toggle, rules)",
7:     getArgumentCompletions: (prefix: string) => {
8:       const subcommands = ["status", "toggle", "rules", "enable", "disable"];
9:       return subcommands
10:         .filter((sc) => sc.startsWith(prefix.trim().toLowerCase()))
11:         .map((sc) => ({ value: sc, label: sc }));
12:     },
13:     handler: async (args, ctx) => {
14:       const parts = args.trim().split(/\s+/);
15:       const action = parts[0]?.toLowerCase() || "status";
16: 
17:       if (action === "toggle") {
18:         const next = !redactor.isEnabled();
19:         redactor.setEnabled(next);
20:         ctx.ui.setStatus("pii-redact", next ? "PII: On" : "PII: Off");
21:         ctx.ui.notify(`PII redaction is now ${next ? "ENABLED" : "DISABLED"}`, "info");
22:         return;
23:       }
24: 
25:       if (action === "enable") {
26:         redactor.setEnabled(true);
27:         ctx.ui.setStatus("pii-redact", "PII: On");
28:         ctx.ui.notify("PII redaction ENABLED", "info");
29:         return;
30:       }
31: 
32:       if (action === "disable") {
33:         redactor.setEnabled(false);
34:         ctx.ui.setStatus("pii-redact", "PII: Off");
35:         ctx.ui.notify("PII redaction DISABLED", "info");
36:         return;
37:       }
38: 
39:       if (action === "rules") {
40:         const rules = redactor.getRules();
41:         const ruleList = rules
42:           .map((r) => `• ${r.name} (${r.id}): ${r.enabled ? "enabled" : "disabled"}`)
43:           .join("\n");
44:         ctx.ui.notify(`Active Redaction Rules:\n${ruleList}`, "info");
45:         return;
46:       }
47: 
48:       // Default: status
